from pathlib import Path
import pandas as pd,numpy as np,json,sys
from scipy import ndimage
from scipy.spatial import cKDTree
root=Path(__file__).resolve().parents[1];base=root;s=sys.argv[1];o=root/s;o.mkdir(exist_ok=True)
if (o/'spatial_metadata.tsv.gz').exists():sys.exit()
d=pd.read_csv(base/s/'bin_metadata.tsv.gz',sep='\t');a=pd.read_csv(base/s/'analysis_metadata.tsv.gz',sep='\t',usecols=['bin_id']);d=d.set_index('bin_id',drop=False);raw=d[d.in_tissue_original==1] if s=='UC_SCC' else d[d.supplied_bin];shape=tuple((d[['array_row','array_col']].max()+1).astype(int));grid=np.zeros(shape,bool);grid[raw.array_row,raw.array_col]=True;lab,n=ndimage.label(grid,structure=np.ones((3,3)));nativesize=np.bincount(lab.ravel());q=d.loc[a.bin_id].copy();assert q.qc_keep.all() and len(q)==len(a);q['spatial_component']=lab[q.array_row,q.array_col];assert (q.spatial_component>0).all();q['component_native_bins']=nativesize[q.spatial_component];q['component_QC_bins']=q.spatial_component.map(q.spatial_component.value_counts());edge=grid&~ndimage.binary_erosion(grid,structure=np.ones((3,3)),border_value=0);dist=ndimage.distance_transform_edt(np.pad(grid,1,constant_values=False))[1:-1,1:-1]*8;q['native_edge_distance_um']=dist[q.array_row,q.array_col];q['native_boundary_bin']=edge[q.array_row,q.array_col];xy=q[['x_um','y_um']].to_numpy();dd,nn=cKDTree(xy).query(xy,k=51,workers=1);dd=dd[:,1:];nn=nn[:,1:];groups=q.spatial_component.to_numpy();cross=groups[nn]!=groups[:,None];q['unrestricted_cross_component_n']=cross.sum(1);q['unrestricted_neighbor50_um']=dd[:,-1]
keep=['bin_id','spatial_component','component_native_bins','component_QC_bins','native_edge_distance_um','native_boundary_bin','unrestricted_cross_component_n','unrestricted_neighbor50_um'];q[keep].to_csv(o/'spatial_metadata.tsv.gz',sep='\t',index=False);q.groupby('spatial_component').agg(n=('bin_id','size'),native_bins=('component_native_bins','first'),x_min=('x_um','min'),x_max=('x_um','max'),y_min=('y_um','min'),y_max=('y_um','max')).reset_index().to_csv(o/'spatial_components.tsv',sep='\t',index=False)
summary=dict(n=len(q),component_count=int(q.spatial_component.nunique()),small_component_bins=int((q.component_QC_bins<=50).sum()),singleton_bins=int((q.component_QC_bins==1).sum()),unrestricted_cross_component_edges=int(cross.sum()),unrestricted_total_edges=int(cross.size),bins_with_cross_component_edges=int(cross.any(1).sum()),distance50_quantiles_um=np.quantile(dd[:,-1],[0,.5,.9,.95,.99,1]).tolist(),rule=('8-connected original in_tissue supplied grid before QC' if s=='UC_SCC' else '8-connected supplied grid before QC; tissue unknown')+'; neighborhood search within component; global scaling',grouping_uses_reference_labels=False);(o/'spatial_input_summary.json').write_text(json.dumps(summary,indent=2));print(s,summary)
